/**
 * BRAND-COLOUR CONTRAST — the shared engine for the coupons surface.
 *
 * WHY THIS FILE EXISTS: a merchant's `Store.brandColor` is DATA, and it is the
 * app's ONE sanctioned exception to "one orange (#EB7100) on one navy ground"
 * (CLAUDE.md). Unvetted brand hexes are exactly how a previous pass shipped
 * white text on Shell's `#FFD500` at a contrast ratio of 1.4. The rule that
 * prevents that had been written twice — once in `app/store/[id].tsx` and once
 * in `components/coupons/StoreTile.tsx` — and a third copy was about to be
 * written for `CouponArtwork`. This is that rule, lifted out once.
 *
 * TWO INDEPENDENT FAILURE MODES, both guarded here:
 *
 *   (a) TOO DARK TO SEE. A brand colour close to the navy ground (#00121D)
 *       is invisible when used as a BARE accent on it (an icon tint, a
 *       hairline, a rim) — Sephora's `#000000` is the sample catalog's own
 *       example. Guarded by `MIN_GROUND_CONTRAST`: below it, decorative
 *       accents fall back to `colors.accent`.
 *   (b) NOT ENOUGH INK CONTRAST. When the brand colour is a FILLED surface
 *       something else sits on top of (an initials disc, a voucher field),
 *       the ink drawn over it must clear a legibility floor. Guarded by
 *       `MIN_INK_CONTRAST`: pick whichever of the app's two approved
 *       "on-colour" inks — `colors.white` or `colors.navy`, the two palette
 *       keys that hold the same value in BOTH modes — contrasts best, per
 *       WCAG's own "test both, use the winner" idiom. If even the winner can't clear the floor, DON'T FILL: the
 *       surface goes neutral and the brand hex is demoted to a rim.
 *
 * Both thresholds are WCAG 2.x contrast RATIOS (`(L1+0.05)/(L2+0.05)`,
 * lighter over darker) computed from sRGB relative luminance — the spec's own
 * contrast-ratio algorithm. `MIN_INK_CONTRAST` (3.0) is the WCAG AA floor for
 * LARGE text and graphical UI components, which is what every consumer here
 * draws (a 20pt+ bold monogram, a 16-54pt bold deal figure).
 * `MIN_GROUND_CONTRAST` (1.5) is deliberately much lower: it is not a
 * legibility floor for text, it is a "can a human tell this pixel apart from
 * the background at all" floor for a thin decorative accent.
 *
 * PURE. No React, no runtime import of the theme — only a TYPE import, so this
 * module can be reasoned about (and one day unit-tested) without a renderer.
 *
 * STILL UNRECONCILED, DELIBERATELY: `components/coupons/CouponRow.tsx:376-402`
 * paints initials on the RAW `store.brandColor` in `colors.buttonText` with no
 * contrast check at all, and `StoreTile.tsx:198-220` keeps its own byte-for-byte
 * copy of `resolveBrandTreatment`. Both are owned by other work in flight. Its
 * own header already commits to that reconciliation being a DELETION, not a
 * redesign — this file is the thing they get deleted in favour of.
 */
type useAppTheme = any; // vendored: was `import type` from '../../theme/useAppTheme'

/** The palette object `useAppTheme()` hands out. Type-only dependency. */
export type ThemeColors = ReturnType<typeof useAppTheme>['colors'];

export const MIN_GROUND_CONTRAST = 1.5;
export const MIN_INK_CONTRAST = 3.0;

/**
 * THE INK POLE — the end of the ramp that moves AWAY from the app's ground:
 * white on the navy ground, navy on the white one (2026-09-15, light mode).
 *
 * Both values come from the palette (`colors.white` / `colors.navy`, the two
 * keys that are deliberately IDENTICAL in both modes), so this is not a theme
 * branch dressed up as maths: it is the one question every lift, wash and
 * hairline below actually asks — "which way is legible from here" — answered
 * from the ground's own luminance instead of from a literal.
 *
 * Before light mode every one of those places wrote the white hex, which is the
 * right answer on navy and the wrong one on white: mixing a wash toward white
 * ON white produces white, i.e. an invisible surface with no error.
 */
export function contrastPole(colors: ThemeColors): string {
  return (luminanceOf(colors.background) ?? 0) < 0.5 ? colors.white : colors.navy;
}

/** `#RGB`, `#RRGGBB` or the bare 6-digit form. Returns null for anything else
 *  — including the `rgba(...)` strings the theme's text ramp uses, which is
 *  why nothing here ever tries to do contrast math on `colors.text`. */
export function hexToRgb(hex: string | undefined | null): [number, number, number] | null {
  if (!hex) return null;
  const value = hex.trim();
  const long = /^#?([0-9a-f]{6})$/i.exec(value);
  if (long) {
    const n = parseInt(long[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  const short = /^#?([0-9a-f]{3})$/i.exec(value);
  if (short) {
    const [r, g, b] = short[1].split('');
    return [parseInt(r + r, 16), parseInt(g + g, 16), parseInt(b + b, 16)];
  }
  return null;
}

function clamp255(n: number): number {
  return Math.max(0, Math.min(255, Math.round(n)));
}

function rgbToHex(rgb: [number, number, number]): string {
  return `#${rgb.map((c) => clamp255(c).toString(16).padStart(2, '0')).join('')}`.toUpperCase();
}

/**
 * Linear interpolation between two hexes in sRGB space, `t` = how much of `b`.
 * sRGB (not linear-light) on purpose: these mixes are being fed straight back
 * into the contrast math below, which is defined on sRGB values, and a
 * gamma-correct blend here would describe a colour we never actually draw.
 * Returns `a` unchanged if either side won't parse.
 */
export function mixHex(a: string, b: string, t: number): string {
  const rgbA = hexToRgb(a);
  const rgbB = hexToRgb(b);
  if (!rgbA || !rgbB) return a;
  const k = Math.max(0, Math.min(1, t));
  return rgbToHex([
    rgbA[0] + (rgbB[0] - rgbA[0]) * k,
    rgbA[1] + (rgbB[1] - rgbA[1]) * k,
    rgbA[2] + (rgbB[2] - rgbA[2]) * k,
  ]);
}

function srgbChannelToLinear(channel255: number): number {
  const c = channel255 / 255;
  return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

export function relativeLuminance(rgb: [number, number, number]): number {
  const [r, g, b] = rgb.map(srgbChannelToLinear);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function contrastRatio(l1: number, l2: number): number {
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

/** Luminance of a hex, or null when it isn't one. */
export function luminanceOf(hex: string | undefined): number | null {
  const rgb = hexToRgb(hex);
  return rgb ? relativeLuminance(rgb) : null;
}

export interface BrandTreatment {
  /** Safe to use directly as a bare accent on the app ground (icon tint,
   *  hairline, rim). Falls back to the theme accent otherwise. */
  accentOnGround: string;
  /** The brand hex, ONLY if a filled surface using it can carry legible ink;
   *  null means "don't fill with this — use a neutral surface and demote the
   *  brand hex to a rim instead". */
  fill: string | null;
  /** The best-contrast ink for text/icons drawn on `fill`, when `fill` is
   *  non-null: `colors.white` or `colors.navy`, the two on-colour inks. */
  ink: string;
}

/**
 * The single-colour case: one flat fill, one ink. This is byte-for-byte the
 * behaviour the store page and `StoreTile` already shipped — lifted, not
 * changed, so adopting it can't move a pixel on either surface.
 */
export function resolveBrandTreatment(
  brandColorHex: string | undefined,
  colors: ThemeColors
): BrandTreatment {
  const rgb = hexToRgb(brandColorHex);
  if (!rgb || !brandColorHex) {
    return { accentOnGround: colors.accent, fill: null, ink: colors.text };
  }
  const brandL = relativeLuminance(rgb);
  const groundL = luminanceOf(colors.background) ?? 0;
  // The two on-colour inks are WHITE and NAVY in BOTH modes, which is why they
  // are read as `colors.white` / `colors.navy` and not as `colors.buttonText` /
  // `colors.background`. Those two used to be the same pair by coincidence: on
  // the navy ground `background` IS navy. In light mode `background` is white,
  // so the pair collapsed to white-and-white and every merchant fill got white
  // ink no matter how pale it was. The fill is the MERCHANT's colour, not a
  // themed surface, so the ink choice must not move with the app's mode.
  const whiteL = luminanceOf(colors.white) ?? 1;
  const navyL = luminanceOf(colors.navy) ?? 0;

  const accentOnGround =
    contrastRatio(brandL, groundL) >= MIN_GROUND_CONTRAST ? brandColorHex : colors.accent;

  const contrastWithWhite = contrastRatio(brandL, whiteL);
  const contrastWithNavy = contrastRatio(brandL, navyL);

  if (Math.max(contrastWithWhite, contrastWithNavy) >= MIN_INK_CONTRAST) {
    return {
      accentOnGround,
      fill: brandColorHex,
      ink: contrastWithWhite >= contrastWithNavy ? colors.white : colors.navy,
    };
  }
  return { accentOnGround, fill: null, ink: colors.text };
}

export interface FieldInk {
  /** `colors.white` or `colors.navy` — whichever survives the whole gradient
   *  best. Mode-independent: see the note in `resolveBrandTreatment`. */
  ink: string;
  /** The WORST contrast that ink achieves across every stop. */
  ratio: number;
  /** `ratio >= MIN_INK_CONTRAST`. False means "don't paint this field". */
  passes: boolean;
}

/**
 * The GRADIENT case, which `resolveBrandTreatment` cannot answer.
 *
 * A gradient field has no single background luminance, and the two ends pull
 * in opposite directions: shading a colour darker helps white ink and hurts
 * navy ink, lightening it does the reverse. Checking only the mid stop is how
 * you ship a figure that is legible in the middle of a voucher and gone at its
 * corner. So each candidate ink is scored by its WORST contrast across ALL
 * stops, and the winner is the one whose worst case is best — a minimax, not
 * an average, because an average lets one unreadable corner hide behind three
 * good ones.
 */
export function pickFieldInk(stops: readonly string[], colors: ThemeColors): FieldInk {
  const luminances = stops
    .map((stop) => luminanceOf(stop))
    .filter((l): l is number => l !== null);

  const candidates = [colors.white, colors.navy];
  let best: FieldInk = { ink: colors.white, ratio: 0, passes: false };

  for (const candidate of candidates) {
    const inkL = luminanceOf(candidate);
    if (inkL === null || luminances.length === 0) continue;
    let worst = Infinity;
    for (const fieldL of luminances) {
      worst = Math.min(worst, contrastRatio(inkL, fieldL));
    }
    if (worst > best.ratio) {
      best = { ink: candidate, ratio: worst, passes: worst >= MIN_INK_CONTRAST };
    }
  }
  return best;
}

/**
 * A hairline that separates a filled shape from the ground it sits on — the
 * other half of failure mode (a). A pure-black voucher on the navy ground is
 * a legible field with an invisible SILHOUETTE; this is what gives it an edge.
 *
 * Neutral (the ink pole at low alpha), NOT `colors.accent`: an orange rim
 * around a merchant's own artwork would put the app's one accent on the one
 * surface CLAUDE.md reserves for merchant identity.
 *
 * The light half is NAVY, not black: `shadowsLight` records why (black on
 * white reads as dirt and pulls the ground toward grey). The dark half is
 * byte-for-byte what it has always been: the palette white at 18% alpha.
 */
export function groundHairline(colors: ThemeColors): string {
  const groundL = luminanceOf(colors.background) ?? 0;
  const pole = groundL < 0.2 ? colors.white : colors.navy;
  return rgbaFromHex(pole, groundL < 0.2 ? 0.18 : 0.14) ?? colors.border;
}

// ── SAME HUE, LEGIBLE (added 2026-09-10, additive) ──────────────────────────
//
// Failure mode (a) above used to be answered by swapping the brand for the app
// orange. On the coupon detail page that read as "the store's coupon is
// orange" (tester, 2026-09-10). `liftToContrast` answers it without leaving the
// merchant's hue: it raises HSL LIGHTNESS only — hue and saturation are held —
// until the colour clears a contrast floor against a given ground. United's
// navy #003057 comes out a readable mid-blue, Chipotle's #A81612 a slightly
// brighter red, Sephora's #000000 (no hue to keep) a graphite grey. A colour
// that already clears the floor is returned UNCHANGED, byte for byte.
//
// IT WALKS AWAY FROM THE GROUND, whichever ground that is. Until light mode
// (2026-09-15) it only ever raised lightness, which is correct on navy and
// exactly backwards on white: every colour that could not reach the floor
// walked UP to pure white and vanished into the page — silently, because a lift
// that fails still returns a colour. The step's SIGN now comes from the
// ground's luminance; on a dark ground the iteration, and its result, are
// unchanged byte for byte.

function rgbToHsl([r, g, b]: [number, number, number]): [number, number, number] {
  const rn = r / 255;
  const gn = g / 255;
  const bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const l = (max + min) / 2;
  if (max === min) return [0, 0, l];
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h: number;
  if (max === rn) h = (gn - bn) / d + (gn < bn ? 6 : 0);
  else if (max === gn) h = (bn - rn) / d + 2;
  else h = (rn - gn) / d + 4;
  return [h / 6, s, l];
}

function hslToRgb([h, s, l]: [number, number, number]): [number, number, number] {
  if (s === 0) return [l * 255, l * 255, l * 255];
  const hueToChannel = (p: number, q: number, t: number) => {
    let k = t;
    if (k < 0) k += 1;
    if (k > 1) k -= 1;
    if (k < 1 / 6) return p + (q - p) * 6 * k;
    if (k < 1 / 2) return q;
    if (k < 2 / 3) return p + (q - p) * (2 / 3 - k) * 6;
    return p;
  };
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  return [hueToChannel(p, q, h + 1 / 3) * 255, hueToChannel(p, q, h) * 255, hueToChannel(p, q, h - 1 / 3) * 255];
}

/** Lightness step per iteration. 0.01 lands within ~0.1 of the floor. */
const LIFT_STEP = 0.01;

/**
 * `hex`, lightened in HSL (hue + saturation kept) just far enough to reach
 * `minRatio` against `againstHex`. Unchanged when it already passes, or when
 * either colour won't parse. See the section note above.
 */
export function liftToContrast(hex: string, againstHex: string, minRatio: number): string {
  const rgb = hexToRgb(hex);
  const groundL = luminanceOf(againstHex);
  if (!rgb || groundL === null) return hex;
  if (contrastRatio(relativeLuminance(rgb), groundL) >= minRatio) return hex;
  const [h, s, l] = rgbToHsl(rgb);
  const step = groundL < 0.5 ? LIFT_STEP : -LIFT_STEP;
  for (let next = l + step; next >= 0 && next <= 1; next += step) {
    const candidate = hslToRgb([h, s, next]);
    if (contrastRatio(relativeLuminance(candidate), groundL) >= minRatio) return rgbToHex(candidate);
  }
  // The end of the ramp, not a chosen colour: lightness 1 is white and 0 is
  // black by definition of HSL. Reached only when no lightness of this hue
  // clears the floor, which cannot happen on either of the app's grounds
  // (white on navy is 15.4:1, black on white 21:1).
  return rgbToHex(hslToRgb([h, s, step > 0 ? 1 : 0]));
}

/** `#RRGGBB` → `rgba(r, g, b, alpha)`; null when it isn't a hex. */
export function rgbaFromHex(hex: string, alpha: number): string | null {
  const rgb = hexToRgb(hex);
  return rgb ? `rgba(${rgb[0]}, ${rgb[1]}, ${rgb[2]}, ${alpha})` : null;
}
